PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE captures (
  run_id TEXT PRIMARY KEY, condition TEXT, harness TEXT, rep INTEGER,
  cold_warm TEXT, started_at_ms INTEGER, exit_code INTEGER,
  wall_ms_measured INTEGER, wall_span_ms INTEGER, model TEXT,
  requests INTEGER, tool_calls INTEGER, total_tokens INTEGER,
  prompt_tokens INTEGER, fresh_input_tokens INTEGER, cached_tokens INTEGER,
  cache_creation_tokens INTEGER, completion_tokens INTEGER,
  cache_hit_rate REAL, cost_token_norm_usd REAL, native_credits REAL,
  quality_score REAL
);
COMMIT;
